use split_decls_genesis :: ourprelude :: * ; use crate :: ffi :: OsStr ; use crate :: path :: { Path , PathBuf , Prefix } ; use crate :: { env , io } ; #[inline] pub fn is_sep_byte (b : u8) -> bool { b == b'/' } #[inline] pub fn is_verbatim_sep (b : u8) -> bool { b == b'/' } #[inline] pub fn parse_prefix (_ : & OsStr) -> Option < Prefix < '_ > > { None } pub const MAIN_SEP_STR : & str = "/" ; pub const MAIN_SEP : char = '/' ; #[doc = " Make a POSIX path absolute without changing its semantics."] pub (crate) fn absolute (path : & Path) -> io :: Result < PathBuf > { let mut components = path . strip_prefix (".") . unwrap_or (path) . components () ; let path_os = path . as_os_str () . as_encoded_bytes () ; let mut normalized = if path . is_absolute () { if path_os . starts_with (b"//") && ! path_os . starts_with (b"///") { components . next () ; PathBuf :: from ("//") } else { PathBuf :: new () } } else { env :: current_dir () ? } ; normalized . extend (components) ; if path_os . ends_with (b"/") { normalized . push ("") ; } Ok (normalized) } pub (crate) fn is_absolute (path : & Path) -> bool { if cfg ! (any (unix , target_os = "hermit" , target_os = "wasi")) { path . has_root () } else { path . has_root () && path . prefix () . is_some () } }